import 'dart:typed_data';

/// Spatial image embedding generated by the EdgeTAM Vision Transformer encoder (Stage 1).
/// Cached on image load and reused for all subsequent point-prompt tap decodes.
class EdgeTamEmbedding {
  static const int gridSize = 64;
  static const int channels = 64;
  static const int totalElements =
      gridSize * gridSize * channels; // 262,144 floats

  final Float32List data;
  final int sourceWidth;
  final int sourceHeight;
  final int activeWidth1024;
  final int activeHeight1024;

  EdgeTamEmbedding({
    required this.data,
    required this.sourceWidth,
    required this.sourceHeight,
    required this.activeWidth1024,
    required this.activeHeight1024,
  }) : assert(
         data.length >= totalElements,
         'Embedding data must contain at least $totalElements elements',
       );
}
